header_type_specs.canonical_declaration:
typedef struct smtp_tcp_callbacks {
    void (* on_accept)(void* user, int fd, const struct sockaddr_storage* peer, socklen_t peer_len);
    void (* on_event)(void* user, int fd, uint32_t events);
    void (* on_close)(void* user, int fd);
} smtp_tcp_callbacks_t;

typedef struct smtp_command {
    smtp_command_kind_t kind;
    char arg[1024];
    bool has_arg;
} smtp_command_t;

typedef struct smtp_mail {
    const char* helo_name;
    const char* auth_user;
    const char* mail_from;
    const char* const* rcpt_to;
    size_t rcpt_count;
    const char* data;
    size_t data_len;
} smtp_mail_t;

typedef enum smtp_auth_state {
    SMTP_AUTH_STATE_NONE = 0,
    SMTP_AUTH_STATE_LOGIN_WAIT_USER,
    SMTP_AUTH_STATE_LOGIN_WAIT_PASS,
    SMTP_AUTH_STATE_PLAIN_WAIT_BLOB,
} smtp_auth_state_t;

typedef struct smtp_session {
    int control_fd;
    smtp_connection_t* conn;
    bool greeted;
    bool authenticated;
    char helo_name[256];
    char auth_user[256];
    smtp_auth_state_t auth_state;
    char auth_login_user[256];
    char mail_from[512];
    bool has_mail_from;
    char rcpt_to[SMTP_MAX_RECIPIENTS][512];
    size_t rcpt_count;
    bool in_data_mode;
    char message_buf[SMTP_MAX_MESSAGE_SIZE + 1];
    size_t message_len;
    bool message_too_large;
} smtp_session_t;
